                )
            )
        );
        UpdateContext(
            {
                locIsVisibleGDPerformRequestofGateApprovalDialog: false,
                locGDPerformRequestofGateApprovalDialogText: $"Cluster data '{locRecordSelectedProjectState.Name}' will be saved."
            }
        )
    ),
