    {
        varApprovalClusterState: LookUp(
            'Project State Trackings',
            ThisRecord.'Project State Tracking' = locRecordSelectedProjectStateTracking.vsb_projectstatetrackingid
        ).'Approval Cluster State',
        varApprovalCheckListState: locSelectedCheckListEntity.'Approval Checklist State',
