            Coalesce(
                LookUp(
                    'Project State Trackings',
                    ThisRecord.'Project State Tracking' = locRecordSelectedProjectStateTracking.vsb_projectstatetrackingid
                ).FlowRunId,
                locSelectedCheckListEntity.'Flow Approval Id',
                Blank()
            )
        )
    },
    Switch(
        locRequestApprovalEntityType,
        "Checklist Completion",
        Or(
            IsBlank(varApprovalCheckListState),
            Not(varApprovalCheckListState in ['Approval Cluster States'.'In Progress' ,'Approval Cluster States'.Completed])
        ),
        "Cluster Transition",
        And(
            locSelectedItemProjectState.HasGate,
            Or(
                Not(varApprovalClusterState in ['Approval Cluster States'.'In Progress','Approval Cluster States'.Completed]) ,
                varApprovalClusterState = 'Approval Cluster States'.'In Progress' && flowIdEmpty
            )
        )
    )
)

UpdateContext(
    {
        locIsVisibleGDPerformRequestofGateApprovalDialog: true,
        locGDPerformRequestofGateApprovalDialogText: $"Please wait..."
    }
);
Switch(
    locRequestApprovalEntityType,
    "Checklist Completion",
    IfError(
        With(
            {
                recCurrentCheckList: Patch(
                    'Project Checklists',
                    locSelectedCheckListEntity,
                    {
                        'Approval Comment': txt_GeneralData_RightPanel_ProjectState_InpForm_Comment_1.Value,
                        'Approval Due Date': If(
