                )
            },
            Trace(
                $"GateApproval 001: Start flow :=> {recCurrentCheckList.'Project Checklist'}",
                TraceSeverity.Information
            );
            UpdateContext({locGDPerformRequestofGateApprovalDialogText: $"Please wait..."});
            With(
                {
                    ProjectGUID: gblRecordSelectedProject.Project,
                    StateTrackingGUID: recCurrentCheckList.'Project Checklist',
                    DefaultApprovalGUID: locSelectedItemProjectState.Gate
                },
