                    gblFlowRequestOfCheckListApproval,
                    PerformCommonRequestofCheckListApproval.Run(
                        ProjectGUID,
                        recCurrentCheckList.'Project Checklist',
                        LookUp(
                            'Check List Default Approvals',
                            ThisRecord.'Project Default Check List'.'Project Default Checklist' = GUID(locSelectedCheckListEntity.'Project Default Checklist')
                        ).'Check List Default Approval',
                        locRecordSelectedProjectState.'Project State'
