                            'Project Checklist Tracking Note',
                            Defaults('Project Checklist Tracking Note'),
                            {
                                Name: $"{If(
                                    gal_Checklist_DisplayProject_Body_General_Content.Selected.ico_Checklist_DisplayProject_Body_Content_ListRow_ApprovalMode.Icon = "People",
                                    "Approval requested",
                                    "Completed and notified about Check List"
