                                            ),
                                            Mail,
                                            Char(13)
                                        ),
                                        "None"
                                    ),
                                    Contributors: Coalesce(
                                        Concat(
                                            ForAll(
                                                Table(ParseJSON(varDefaultApprovals.'Default Contributors')),
                                                {Mail: Value.PersonaRole}
                                            ),
                                            Mail,
                                            Char(13)
                                        ),
                                        "None"
                                    ),
                                    Notifications: Coalesce(
                                        Concat(
                                            ForAll(
                                                Table(ParseJSON(varDefaultApprovals.'Default Notifications')),
                                                {Mail: Value.PersonaRole}
                                            ),
                                            Mail,
                                            Char(13)
                                        ),
                                        "None"
                                    )
                                }]
                            ),
                            'Last Triggered Approval Mode': varDefaultApprovals.'Approval Mode'
                        }
                    )
                },
                Trace(
                    $"GateApproval 001: Start flow :=> {recCurrentProjectStateTracking.'Project State Tracking'}",
                    TraceSeverity.Information
                );
                UpdateContext({locGDPerformRequestofGateApprovalDialogText: $"Please wait..."});
                With(
                    {
                        ProjectGUID: gblRecordSelectedProject.Project,
                        StateGUID: locRecordSelectedProjectState.'Project State',
