                        gblFlowRequestOfGateApproval,
                        PerformCommonRequestofGateApproval.Run(
                            ProjectGUID,
                            StateGUID,
                            StateTrackingGUID,
                            DefaultApprovalGUID
                        )
                    );
                    If(
                        Not(IsBlank(gblFlowRequestOfGateApproval.runid)),
                        UpdateIf(
                            colSelectedProjectStateTracking,
                            ID = recCurrentProjectStateTracking.'Project State Tracking',
                            {
                                StateProgress: 'Approval Cluster States'.'In Progress',
                                FlowRunId: gblFlowRequestOfGateApproval.runid,
                                FlowApprovalId: Coalesce(
                                    gblFlowRequestOfGateApproval.approvalid,
                                    Blank()
                                )
                            }
                        )
                    );
                    UpdateContext(
                        {
                            locIsVisibleGDPerformRequestofGateApprovalDialog: false,
                            locCurrentClusterStateNote: Patch(
                                'Project State Tracking Notes',
                                Defaults('Project State Tracking Notes'),
                                {
                                    Name: $"Approval requested - {gblRecordSelectedProject.'Project Name'}, {locRecordSelectedProjectState.Name}",
                                    'Project State Tracking': recCurrentProjectStateTracking,
                                    Comment: $"Approval requested - {Trim(txt_GeneralData_RightPanel_ProjectState_InpForm_Comment_1.Value)}",
                                    Note: html_CheckList_RightPanel_ChangeCluster_Form_History.HtmlText,
                                    'Note Type': 'Note Type'.Checklistitem,
                                    'Owning Business Unit': gblRecordSelectedProject.'Besitzer (Unternehmenseinheit)'
                                }
                            )
                        }
                    )
                );
            )
        ),
        // Show error message
        UpdateContext({locGDPerformRequestofGateApprovalDialogText: $"Error: Project Status was updated.  Internal error: originated on {FirstError.Source}. Message: {FirstError.Message & FirstError.Details.HttpResponse}"})
    ),
    false
);
UpdateContext(
    {
        locIsVisibleRightPanelProjectState: false,
        locIsVisibleGDPerformRequestofGateApprovalDialog: false,
        locGDPerformRequestofGateApprovalDialogText: Blank()
    }
);
Refresh('Project State Trackings');
Select(btn_CheckList_RightPanel_ChangeCluster_Form_Buttons_Reset);
Select(btn_CheckList_RightPanel_ChangeCluster_Form_Buttons_Refresh);
Select(but_Project_States_CheckList_Refresh);
Navigate('Project General CheckList Screen');

ControlPropertyState.AutoRuleBindingString:
UpdateContext(
    {
        locIsVisibleGDPerformRequestofGateApprovalDialog: true,
        locGDPerformRequestofGateApprovalDialogText: $"Request Approval for '{locRecordSelectedProjectState.Value}' has been sent, please wait..."
    }
);
IfError(
    With(
        {
            varCurrentClusterState: Patch(
                'Project State Trackings',
                If(
                    IsBlank(locRecordSelectedProjectStateTracking),
                    Defaults('Project State Trackings'),
                    LookUp(
                        'Project State Trackings',
                        'Project State Tracking' = locRecordSelectedProjectStateTracking.'Project State Tracking'
                    )
                ),
                {
                    Project: gblRecordSelectedProject,
                    'Cluster Project Status': LookUp(
                        'Custom Choice Values',
                        'Custom Choice Value' = locRecordSelectedProjectState.'Custom Choice Value'
                    ),
                    'Approval Comment': txt_GeneralData_RightPanel_ProjectState_InpForm_Comment_1.HtmlText,
                    'Approval Due Date': dtp_GeneralData_RightPanel_ProjectState_InpForm_ApprovalDueDate_1.SelectedDate,
                    'Approval Cluster State': 'Approval Cluster States'.'In Progress',
                    'Owning Business Unit': gblRecordSelectedProject.'Besitzer (Unternehmenseinheit)'
                }
            )
        },
        Set(
            gblRecordSelectedProject,
            Patch(
                Projects,
                If(
                    IsBlank(gblRecordSelectedProject),
                    Defaults(Projects),
                    gblRecordSelectedProject
                ),
                {
                    'Cluster Project Status': LookUp(
                        'Custom Choice Values',
                        'Custom Choice Value' = locRecordSelectedProjectState.'Custom Choice Value'
                    ),
                    'Besitzer (Unternehmenseinheit)': gblRecordSelectedProject.'Besitzer (Unternehmenseinheit)'
                }
            )
        );
        Trace(
            $"GateApproval 001: Start flow :=> {varCurrentClusterState.'Project State Tracking'}",
            TraceSeverity.Information
        );
        UpdateContext({locGDPerformRequestofGateApprovalDialogText: $"Request data was '{locRecordSelectedProjectState.Value}' successfully saved."});
        With(
            {
                varPortfolioManager: LookUp(
                    'Project Default Approvals',
                    ThisRecord.'Project Default Approvals' = GUID(locSelectedItemProjectState.Gate)
                ).'Approval participant 1',
                varControllingManager: LookUp(
                    'Project Default Approvals',
                    ThisRecord.'Project Default Approvals' = GUID(locSelectedItemProjectState.Gate)
                ).'Approval participant 2'
            },
            With(
                {
                    varProject: {
                        ProjectGuid: gblRecordSelectedProject.Project,
                        ProjectId: gblRecordSelectedProject.'Project ID',
                        ProjectName: gblRecordSelectedProject.'Project Name',
                        StateGuid: locRecordSelectedProjectState.'Custom Choice Value',
                        StateName: locRecordSelectedProjectState.Value,
                        StateTrackingGuid: varCurrentClusterState.'Project State Tracking',
                        HasGate: locSelectedItemProjectState.HasGate,
                        GateSettingsGuid: locSelectedItemProjectState.Gate,
                        PortfolioManager: If(
                            Not(IsBlank(varPortfolioManager)),
                            varPortfolioManager.Mail,
                            ""
                        ),
                        ControllingManager: If(
                            Not(IsBlank(varControllingManager)),
                            varControllingManager.Mail,
                            ""
                        )
                    }
                },
                Set(
                    gblFlowRequestOfGateApproval,
                    PerformRequestofGateApproval.Run(JSON(varProject))
                );
                UpdateIf(
                    colSelectedProjectStateTracking,
                    ID = varCurrentClusterState.'Project State Tracking',
                    {
                        StateProgress: 'Approval Cluster States'.'In Progress',
                        FlowRunId: Blank(),
                        FlowApprovalId: Blank()
                    }
                );
            )
        )
    ),
    // Show error message
    UpdateContext({locGDPerformRequestofGateApprovalDialogText: $"Error: Project Status was updated.  Internal error: originated on {FirstError.Source}. Message: {FirstError.Message & FirstError.Details.HttpResponse}"})
);
UpdateContext(
    {
        locIsVisibleRightPanelProjectState: false,
        locIsVisibleGDPerformRequestofGateApprovalDialog: false,
        locGDPerformRequestofGateApprovalDialogText: Blank()
    }
);
Select(btn_GeneralData_RightPanel_ProjectState_Buttons_Refresh_1);
Select(btn_GeneralData_RightPanel_ProjectState_Buttons_Reset_1);

With(
    {
        varSelectedProjectStateTracking: LookUp(
            'Project State Trackings',
            ThisRecord.'Project State Tracking' = GUID(locRecordSelectedProjectStateTracking.'Project State Tracking')
        )
    },
    And(
        locSelectedItemProjectState.HasGate,
        IsBlank(varSelectedProjectStateTracking.FlowApprovalId),
        IsBlank(varSelectedProjectStateTracking.FlowRunId)
    )
)

Rules.InvariantScript:
Table(
    {
        ItemKey: "closeKey",
        ItemDisplayName: "Home",
        ItemIconName: "ChromeClose",
        ItemIconOnly: true,
        ItemFarItem: true,
        ItemIconColor: gblAppTheme.palette.themeTertiary
    }
)

If(
    !IsBlank(Self.Selected.ItemKey) && Self.Selected.ItemKey = "closeKey",
    Reset(txt_CheckList_RightPanel_BodyForm_Comments);
    UpdateContext(
        {
            locIsVisibleRightPanelEditCheckList: false,
            locSelectedCheckListEntity: Blank()
        }
    )
);

UpdateContext(
    {
        locGeneralDataIsSavingDialogVisible: true,
        locGeneralDataSavingDialogText: $"The state of task '{locSelectedCheckListEntity.Name}' will be changed, please wait..."
    }
);
IfError(
    UpdateContext({locGeneralDataSavingDialogText: $"Task state was successfully changed."});
    UpdateContext(
        {
            locUpdatedCheckListEntity: Patch(
                'Project Checklists',
                LookUp(
                    'Project Checklists',
                    'Project Checklist' = locSelectedCheckListEntity.'Project Checklist'
                ),
                {Comments: Trim(txt_CheckList_RightPanel_BodyForm_Comments.Value)}
            )
        }
    );
    UpdateIf(
        colProjectCheckList,
        ThisRecord.ID = locSelectedCheckListEntity.'Project Checklist',
        {Note: Trim(txt_CheckList_RightPanel_BodyForm_Comments.Value)}
    ),
    UpdateContext({locGeneralDataSavingDialogText: $"Error: Task state could not be changed. Internal error: originated on {FirstError.Source}. Message: {FirstError.Message} {FirstError.Details.HttpResponse}"})
);
UpdateContext(
    {
        locGeneralDataIsSavingDialogVisible: false,
        locGeneralDataSavingDialogText: Blank(),
        locIsVisibleRightPanelEditCheckList: false,
        locSelectedCheckListEntity: Blank()
    }
);

ControlPropertyState.AutoRuleBindingString:
If(
    And(
        CountRows(
            Filter(
                colPanelShareholdingEntityFormValidation,
                Valid = false
            )
        ) = 0,
        CountRows(
            Filter(
                colPanelShareholdingEntityFormValidation,
                Dirty = true
            )
        ) > 0
    ),
    DisplayMode.Edit,
    DisplayMode.Disabled
)

Rules.InvariantScript:
IfError(
    With(
        {
            varRecordSelectedProjectStateTracking: First(
                Filter(
                    'Project State Trackings',
                    And(
                        ThisRecord.Project.Project = gblRecordSelectedProject.Project,
                        Or(
                            ThisRecord.'Approval Cluster State' = 'Approval Cluster States'.'In Progress',
                            ThisRecord.'Approval Cluster State' = 'Approval Cluster States'.Abandoned,
                            ThisRecord.'Approval Cluster State' = 'Approval Cluster States'.'Inactive/ On-hold'
                        )
                    )
                )
            )
        },
        Trace($"Try to set 'Approval Cluster State' to {locChangeClusterStateConfirmationDialogApprovalClusterStateValue}", TraceSeverity.Information);
        If(
            Not(IsBlank(varRecordSelectedProjectStateTracking)),
            UpdateContext(
                {
                    locRecordUpdatedProjectStateTracking: Patch(
                        'Project State Trackings',
                        varRecordSelectedProjectStateTracking,
                        {
                            Project: gblRecordSelectedProject,
                            'Approval Cluster State': locChangeClusterStateConfirmationDialogApprovalClusterStateValue,
                            'Owning Business Unit': gblRecordSelectedProject.'Besitzer (Unternehmenseinheit)'
                        }
                    )
                }
            );
            Set(
                gblRecordSelectedProject,
                Patch(
                    Projects,
                    gblRecordSelectedProject,
                    {
                        'Cluster State': locChangeClusterStateConfirmationDialogValue,
                        'Besitzer (Unternehmenseinheit)':gblRecordSelectedProject.'Besitzer (Unternehmenseinheit)'
                    }
                )
            );
            UpdateIf(
                'Project State Trackings',
                And(
                    ThisRecord.Project.Project = gblRecordSelectedProject.Project,
                    Or(
                        ThisRecord.'Approval Cluster State' = 'Approval Cluster States'.'Request canceled',
                        ThisRecord.'Approval Cluster State' = 'Approval Cluster States'.Rejected
                    )
                ),
                {'Approval Cluster State': 'Approval Cluster States'.'Not Started'}
            )
        );
    );
    Set(
        gblProjectHeaderData,
        {
            ID: gblRecordSelectedProject.Project,
            Name: gblRecordSelectedProject.'Project Name',
            Technology: Text(gblRecordSelectedProject.Technology),
            Capacity: gblRecordSelectedProject.'Plant WTG Capacity [MW]',
            Status: gblRecordSelectedProject.'Cluster State'.Name,
            Approval: Text(gblRecordSelectedProject.'Approval States')
        }
    );
    Select(btn_CheckList_RightPanel_ChangeCluster_Form_Buttons_Refresh),
    UpdateContext({locGDPerformRequestofGateApprovalDialogText: $"Error: Cluster state could not be changed. Internal error: originated on {FirstError.Source}. Message: {FirstError.Message} {FirstError.Details.HttpResponse}"})
);
UpdateContext({locChangeClusterStateConfirmationDialog: false});

UpdateContext({locLeaveGeneralDataConfirmationDialog: false});
If(
    cmp_CheckList_Left_Navigation.SelectedKey <> gblLeftNavigationSelected.ItemKey,
    Set(
        gblLeftNavigationSelected,
        LookUp(
            LeftNavigationMenu,
            ItemKey = cmp_CheckList_Left_Navigation.SelectedKey
        )
    );
    Navigate(gblLeftNavigationSelected.TargetScreen),
    Navigate(
        'Project Main Screen',
        ScreenTransition.Fade
    )
)

UpdateContext(
    {
        locChangeClusterStateReturnConfirmationDialog: false,
        locIsVisibleGDPerformRequestofGateApprovalDialog: true,
        locGDPerformRequestofGateApprovalDialogText: $"Return to {locSelectedItemProjectPreviousState.Name}, please wait..."
    }
);
IfError(
    With(
        {
            varCurrentClusterState: Patch(
                'Project State Trackings',
                LookUp(
                    'Project State Trackings',
                    And(
                        Project.Project = gblRecordSelectedProject.Project,
                        'Cluster State'.'Project State' = GUID(locSelectedItemProjectState.ID)
                    )
                ),
                {
                    'Approval Cluster State': 'Approval Cluster States'.'Not Started',
                    'Owning Business Unit': gblRecordSelectedProject.'Besitzer (Unternehmenseinheit)'
                }
            ),
            varPreviousClusterState: Patch(
                'Project State Trackings',
                LookUp(
                    'Project State Trackings',
                    And(
                        Project.Project = gblRecordSelectedProject.Project,
                        'Cluster State'.'Project State' = GUID(locSelectedItemProjectPreviousState.ID)
                    )
                ),
                {
                    'Approval Cluster State': 'Approval Cluster States'.'In Progress',
                    FlowApprovalId: Blank(),
                    FlowRunId: Blank(),
                    'Owning Business Unit': gblRecordSelectedProject.'Besitzer (Unternehmenseinheit)'
                }
            )
        },
        UpdateIf(
            colSelectedProjectStateTracking,
            ID = locRecordSelectedProjectStateTracking.vsb_projectstatetrackingid,
            {StateProgress: 'Approval Cluster States'.'Not Started'}
        );
        UpdateContext(
            {
                locCurrentClusterStateNote: Patch(
                    'Project State Tracking Notes',
                    Defaults('Project State Tracking Notes'),
                    {
                        Name: $"Project was reset to {locSelectedItemProjectPreviousState.Name}",
                        'Project State Tracking': varCurrentClusterState,
                        Comment: Trim(txt_GeneralData_RightPanel_ProjectState_InpForm_Comment_1.Value),
                        //Note: html_GeneralData_RightPanel_ProjectState_InpForm_History.HtmlText,
                        'Note Type': 'Note Type'.None,
                        'Owning Business Unit': gblRecordSelectedProject.'Besitzer (Unternehmenseinheit)'
                    }
                )
            }
        );
    ),
    UpdateContext({locGDPerformRequestofGateApprovalDialogText: $"Error: Project Status was updated.  Internal error: originated on {FirstError.Source}. Message: {FirstError.Message & FirstError.Details.HttpResponse}"})
);
UpdateContext(
    {
        locIsVisibleGDPerformRequestofGateApprovalDialog: false,
        locGDPerformRequestofGateApprovalDialogText: Blank()
    }
);
Navigate('Project General CheckList Screen');

ClearCollect(
    colChecklistAllProjectStates,
    ForAll(
        Sort(
            Filter(
                'Project States',
                ThisRecord.'Is Visible On Checklist' = true
            ),
            Order,
            SortOrder.Ascending
        ) As Source,
        With(
            {
                varClusterNo: Switch(
                    Source.Name,
                    "Draft", 0,
                    "Cluster 1", 1,
                    "Cluster 2", 2,
                    "Cluster 3", 3,
                    "Cluster 4", 4,
                    "Cluster 5", 5,
                    "Cluster 6", 6,
                    999
                )
            },
            With(
                {
                    varGateSourceNo: If(
                        Source.Name = "Draft" && locProjectStartClusterNo > 0,
                        If(
                            locProjectStartClusterNo = 1,
                            0,
                            locProjectStartClusterNo - 1
                        ),
                        varClusterNo
                    )
                },
                With(
                    {
                        varGateSourceState: LookUp(
                            AddColumns(
                                Filter(
                                    'Project States' As GateState,
                                    GateState.'Is Visible On Checklist' = true
                                ) As GateState,
                                ClusterNoForGate,
                                Switch(
                                    GateState.Name,
                                    "Draft", 0,
                                    "Cluster 1", 1,
                                    "Cluster 2", 2,
                                    "Cluster 3", 3,
                                    "Cluster 4", 4,
                                    "Cluster 5", 5,
                                    "Cluster 6", 6,
                                    999
                                )
                            ),
                            ClusterNoForGate = varGateSourceNo
                        )
                    },
                    With(
                        {
                            varGateRecord: LookUp(
                                colDefaultProjectApprovalsSettings As Approval,
                                Not(IsBlank(Approval.'Cluster State')) &&
                                Approval.'Cluster State'.'Project State' = varGateSourceState.'Project State'
                            )
                        },
                        {
                            ID: Source.'Project State',
                            Name: Source.Name,
                            Description: Coalesce(
                                Source.'Cluster Description',
                                Source.Name
                            ),
                            State: LookUp(
                                colSelectedProjectStateTracking,
                                ClusterProjectStateID = Source.'Project State'
                            ),
                            HasGate: Not(IsBlank(varGateRecord)),
                            Gate: varGateRecord.'Project Default Approvals',
                            Sort: Source.Order,
                            ClusterNo: varClusterNo
                        }
                    )
                )
            )
        )
    )
);

// Operational collection.
// Used for approval movement logic.
// Keep this filtered so Draft still moves to Start Cluster correctly.
ClearCollect(
    colProjectStatesForChecklist,
    With(
        {
            varFilteredStates: Filter(
                colChecklistAllProjectStates,
                ClusterNo = 0 ||
                (
                    ClusterNo >= locProjectStartClusterNo &&
                    ClusterNo <= 6
                )
            )
        },
        ForAll(
            Sequence(CountRows(varFilteredStates)),
            Patch(
                Last(
                    FirstN(
                        varFilteredStates,
                        Value
                    )
                ),
                {
                    RowNumber: Value
                }
            )
        )
    )
);

// Display collection.
// Used only by the visual cluster component.
// Shows Draft + skipped/completed clusters + remaining clusters.
ClearCollect(
    colProjectStatesForChecklistDisplay,
    ForAll(
        Sequence(CountRows(colChecklistAllProjectStates)),
        With(
            {
                varDisplayRow: Last(
                    FirstN(
                        colChecklistAllProjectStates,
                        Value
                    )
                )
            },
            Patch(
                varDisplayRow,
                {
                    RowNumber: Value,
                    IsSkippedDisplayOnly: varDisplayRow.ClusterNo > 0 &&
                        varDisplayRow.ClusterNo < locProjectStartClusterNo
                }
            )
        )
    )
);

UpdateContext(
    {
        locDefaultFirstProjectStateInProgress: Coalesce(
            LookUp(
                colProjectStatesForChecklist,
                State.StateProgress = 'Approval Cluster States'.'In Progress'
            ),
            First(colProjectStatesForChecklist)
        )
    }
)
